#!/usr/bin/env bash
# Shared helpers for the release PR body and its hand-written summary region.
#
# The release PR body is split in two by a marker line: everything above it
# is written by a human and is preserved across regeneration, everything
# below it is rebuilt from `git log` on every push to main. The summary
# region is what the Release workflow publishes as the GitHub Release body.
# The layout and the marker are documented in docs/guides/release.md.
#
# Usage:
#   source release-summary.sh
#   summary=$(summary_region "$body")
#
# Every function here is pure text manipulation — no network, no GitHub CLI
# — so release-summary.test.sh can exercise them offline. The PR lookup that
# needs the GitHub CLI lives in release-pr-lookup.sh instead.

# The single definition of the marker that separates the human region from
# the machine-generated changelog.
changelog_marker() {
    printf '%s\n' '<!-- changelog:auto -->'
}

# The sentinel left in a freshly generated body, marking a summary that has
# not been written yet.
summary_sentinel() {
    printf '%s\n' '<!-- release-summary:todo -->'
}

# The starting point for a summary nobody has written yet.
summary_placeholder() {
    cat <<EOF
## Summary

$(summary_sentinel)
_Write the release summary here. It becomes the body of the GitHub Release.
Delete the marker comment above once written._
EOF
}

# Echo everything above the first occurrence of the marker, with trailing
# blank lines trimmed. Echo nothing when the marker is absent: such a body
# was not generated by create-release-pr.sh, so it carries no summary to
# preserve.
#
# The split is on the exact marker string rather than a regular expression,
# so arbitrary Markdown in the human region (code fences, nested comments,
# horizontal rules) cannot corrupt it.
summary_region() {
    local body="$1"
    local marker region

    marker=$(changelog_marker)
    if [[ "$body" != *"$marker"* ]]; then
        return 0
    fi

    # `%%` strips the longest suffix starting at the marker, i.e. the split
    # happens at its first occurrence.
    region="${body%%"$marker"*}"
    region="${region%"${region##*[![:space:]]}"}"

    if [ -z "$region" ]; then
        return 0
    fi
    printf '%s\n' "$region"
}

# True when the summary cannot serve as a release body: empty, whitespace
# only once HTML comments are removed, or still carrying the sentinel.
summary_is_unwritten() {
    local summary="$1"
    local sentinel stripped

    sentinel=$(summary_sentinel)
    if [[ "$summary" == *"$sentinel"* ]]; then
        return 0
    fi

    stripped=$(strip_html_comments "$summary")
    [ -z "${stripped//[[:space:]]/}" ]
}

# Remove every complete `<!-- ... -->` comment, including multi-line ones.
strip_html_comments() {
    local text="$1"
    local head tail

    while [[ "$text" == *'<!--'*'-->'* ]]; do
        head="${text%%'<!--'*}"
        tail="${text#*'<!--'}"
        tail="${tail#*'-->'}"
        text="${head}${tail}"
    done
    printf '%s' "$text"
}

# The compare section of the body: the commits since last_tag, up to `head`
# (the release branch while the PR is open; update-release-pr-links.sh
# rewrites it to the tag once the release is cut). Nothing when there is no
# tag to compare against.
compare_section() {
    local repo_url="$1"
    local last_tag="$2"
    local version="$3"
    local head="$4"

    if [ -z "$last_tag" ]; then
        return 0
    fi
    cat <<EOF
## Changelog

- [${last_tag}...v${version}](${repo_url}/compare/${last_tag}...${head})
EOF
}

# A release PR body: the summary region, the marker, then the generated
# changelog and the compare section.
render_release_pr_body() {
    local summary="$1"
    local changelog="$2"
    local compare="$3"

    cat <<EOF
${summary}

$(changelog_marker)

${changelog}
${compare}
EOF
}

# Regenerate a release PR body from its current one: the summary region is
# carried over verbatim (or starts from the placeholder when there is none),
# and everything below the marker is replaced.
regenerate_release_pr_body() {
    local old_body="$1"
    local changelog="$2"
    local compare="$3"
    local summary

    summary=$(summary_region "$old_body")
    if [ -z "$summary" ]; then
        summary=$(summary_placeholder)
    fi
    render_release_pr_body "$summary" "$changelog" "$compare"
}

# Point the compare link at the tag instead of the (deleted) release branch,
# rewriting only the region below the marker, so a hand-written summary that
# mentions the branch is left untouched. A body without the marker carries
# no summary, so it is rewritten whole.
rewrite_compare_link() {
    local body="$1"
    local branch="$2"
    local version="$3"
    local marker head tail

    marker=$(changelog_marker)
    if [[ "$body" == *"$marker"* ]]; then
        head="${body%%"$marker"*}${marker}"
        tail="${body#*"$marker"}"
    else
        head=""
        tail="$body"
    fi

    printf '%s%s\n' "$head" "${tail//"...${branch})"/"...v${version})"}"
}
